import { readFileSync } from 'node:fs';
import { total as oldTotal } from './cart.orig.js';
import { total as newTotal } from '../src/cart.js';

const orders = JSON.parse(readFileSync(new URL('../data/orders-2026-10.json', import.meta.url), 'utf8'));
let same0 = 0, diff0 = 0;
// (a) 10 月の注文の items を、割引率 0 で
for (const o of orders) (oldTotal(o.items, 0) === newTotal(o.items, 0) && oldTotal(o.items) === newTotal(o.items)) ? same0++ : diff0++;
// (b) 乱数のカート（種を固定）: 1〜15 行、価格 1〜99,999、数量 1〜20、割引率 0
let s = 12345; const rnd = (n) => (s = (s * 1103515245 + 12345) % 2147483648, s % n);
let rs = 0, rd = 0;
for (let i = 0; i < 200000; i++) {
  const items = Array.from({ length: 1 + rnd(15) }, () => ({ price: 1 + rnd(99999), qty: 1 + rnd(20) }));
  oldTotal(items, 0) === newTotal(items, 0) ? rs++ : rd++;
}
console.log(`discount 0 / October items: same=${same0} diff=${diff0}`);
console.log(`discount 0 / random carts:  same=${rs} diff=${rd}`);
// (c) 10 月の注文を、その注文の割引率で（個人の欄は出さない）
